mod sampling;
use alloy_primitives::{B256, hex, keccak256_uncached};
use sampling::Case;
use std::{fs, hint::black_box, io, time::Instant};

struct Input {
    key: B256,
    message: B256,
    signature: [u8; 7740],
    parsed_key: reference_sphincs::LeanSphincsPublicKey,
    parsed_signature: reference_sphincs::LeanSphincsSignature,
}

fn main() {
    let args: Vec<_> = std::env::args().collect();
    let corpus: serde_json::Value = serde_json::from_slice(&fs::read(&args[1]).unwrap()).unwrap();
    let mut inputs = Vec::new();
    for item in corpus["cases"].as_array().unwrap() {
        let key = B256::from(hex::decode_to_array::<_, 32>(item["public_key"].as_str().unwrap()).unwrap());
        let message = B256::from(hex::decode_to_array::<_, 32>(item["message"].as_str().unwrap()).unwrap());
        let signature = hex::decode_to_array::<_, 7740>(item["signature"].as_str().unwrap()).unwrap();
        let parsed_key = reference_sphincs::LeanSphincsPublicKey::from_bytes(&key.0);
        let parsed_signature = reference_sphincs::LeanSphincsSignature::from_bytes(&signature);
        assert_eq!(parsed_key.to_bytes(), key.0);
        assert_eq!(parsed_signature.to_bytes(), signature);
        inputs.push(Input {key, message, signature, parsed_key, parsed_signature});
    }
    let expected = [16, 24, 10, 64, 3, 128, 8, 8, 10, 32, 32, 7740];
    assert_eq!(audit_native::audit_parameters(), expected);
    use reference_sphincs::internals as p;
    assert_eq!([p::N, p::FORS_TREES, p::FORS_HEIGHT, p::V, p::CHAIN_LEN-1,
        p::TARGET_SUM, p::LAYER_HEIGHTS[0], p::LAYER_HEIGHTS[1], p::LAYER_HEIGHTS[2],
        reference_sphincs::PUB_KEY_SIZE, reference_sphincs::MESSAGE_LEN, reference_sphincs::SIG_SIZE], expected);
    type Verify = fn(&B256, &B256, &[u8]) -> bool;
    let implementations: [(&str, Verify); 5] = [
        ("ours_original", ours_original::verify),
        ("ours_copy_native", audit_native::verify),
        ("ours_no_fors_batch", audit_no_fors::verify),
        ("ours_no_wots_batch", audit_no_wots::verify),
        ("ours_no_batch", audit_scalar::verify),
    ];
    let mut cases = Vec::new();
    let mut invalid_checks = 0;
    for (name, verify) in implementations {
        for input in &inputs {
            assert!(verify(&input.key, &input.message, &input.signature));
            let mut sig = input.signature;
            for at in [0, 15, 16, 100, 4239, 4240, 4243, 5268, 5395, 5396, 6551, 6552, 7739] {
                sig[at] ^= 1;
                let want = reference_sphincs::verify(&input.parsed_key, &input.message.0,
                    &reference_sphincs::LeanSphincsSignature::from_bytes(&sig));
                assert!(!want);
                assert_eq!(verify(&input.key, &input.message, &sig), want);
                invalid_checks += 1;
                sig[at] ^= 1;
            }
        }
        let inputs = &inputs;
        cases.push(Case {name:name.into(), work_items:1, operation:Box::new(move |i| {
            let input = &inputs[i % inputs.len()];
            black_box(verify(black_box(&input.key), black_box(&input.message), black_box(&input.signature)));
        })});
    }
    cases.push(Case {name:"leanVM_native".into(), work_items:1, operation:Box::new(|i| {
        let input = &inputs[i % inputs.len()];
        black_box(reference_sphincs::verify(black_box(&input.parsed_key),
            black_box(&input.message.0), black_box(&input.parsed_signature)));
    })});
    let image = [77u8;80];
    cases.push(Case {name:"alloy_asm_hash80".into(), work_items:1, operation:Box::new(move |_| {
        black_box(keccak256_uncached(black_box(image)));
    })});
    cases.push(Case {name:"leanVM_hash80".into(), work_items:1, operation:Box::new(move |_| {
        black_box(reference_keccak::hash(black_box(&image)));
    })});
    assert_eq!(keccak256_uncached(image).0, reference_keccak::hash(&image));
    eprintln!("checked {} fixtures and {invalid_checks} mutation cases", inputs.len());
    let mut start = String::new();
    io::stdin().read_line(&mut start).unwrap();
    let now = Instant::now();
    let results = sampling::measure(&mut cases, 44, 20, 300, args[3].parse().unwrap(), |_| {});
    fs::write(&args[2], serde_json::to_vec_pretty(&serde_json::json!({
        "parameters":expected,"fixture_count":inputs.len(),"mutation_checks":invalid_checks,
        "avx2":cfg!(target_feature="avx2"),"avx512f":cfg!(target_feature="avx512f"),
        "debug_assertions":cfg!(debug_assertions),"elapsed_seconds":now.elapsed().as_secs_f64(),
        "measurements":results
    })).unwrap()).unwrap();
}

