use alloy_primitives::{B256,hex};
use std::{collections::BTreeMap,fs};
fn main() {
    let args:Vec<_>=std::env::args().collect();
    let j:serde_json::Value=serde_json::from_slice(&fs::read(&args[1]).unwrap()).unwrap();
    let mut results=Vec::new();
    for item in j["cases"].as_array().unwrap() {
        let key=B256::from(hex::decode_to_array::<_,32>(item["public_key"].as_str().unwrap()).unwrap());
        let message=B256::from(hex::decode_to_array::<_,32>(item["message"].as_str().unwrap()).unwrap());
        let sig=hex::decode_to_array::<_,7740>(item["signature"].as_str().unwrap()).unwrap();
        assert!(trace_ours::verify(&key,&message,&sig));
        let mut our_images=trace_ours::audit_trace::take();
        assert!(trace_ref::verify(&trace_ref::LeanSphincsPublicKey::from_bytes(&key.0),
            &message.0,&trace_ref::LeanSphincsSignature::from_bytes(&sig)));
        let mut ref_images=trace_keccak::audit_trace::take();
        let actual_permutations=trace_keccak::audit_trace::take_permutations();
        our_images.sort();ref_images.sort();
        assert_eq!(our_images,ref_images,"all logical hash preimages must match");
        let mut lengths=BTreeMap::new();
        for image in &our_images {*lengths.entry(image.len()).or_insert(0usize)+=1;}
        let permutations:usize=our_images.iter().map(|b|b.len()/136+1).sum();
        assert_eq!(permutations,515);
        assert_eq!(actual_permutations,515);
        assert_eq!(our_images.len(),491);
        let encoded:Vec<_>=our_images.iter().map(|b|hex::encode(b)).collect();
        results.push(serde_json::json!({"name":item["name"],"hash_calls":our_images.len(),
            "permutations_per_implementation":permutations,"upstream_counter":actual_permutations,
            "preimage_length_histogram":lengths,"identical_sorted_preimages":encoded}));
    }
    fs::write(&args[2],serde_json::to_vec_pretty(&results).unwrap()).unwrap();
    println!("{} fixtures: all 491 hash preimages identical; 515 logical permutations each",results.len());
}
